import fs from 'node:fs';import path from 'node:path';import readline from 'node:readline';import {createHash} from 'node:crypto';import {performance} from 'node:perf_hooks';import {createBookPublicationState,applyBookPublication} from '../live-paper/book-publication-v2.mjs';import {sealedNativePrefix} from '../live-paper/native-dip-host-v1.mjs';import {createInventoryQuoteWalletV1,advanceInventoryQuoteWalletV1,inventoryQuoteWalletReportV1} from '../paper/inventory-quote-wallet-v1.mjs';
const begun=performance.now(),rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),file=path.join(rt,'public-books.jsonl'),seal=sealedNativePrefix(file),base={cutoff:'2026-10-06T00:00:00.000Z',initialCash:'100.000000',maximumCommitted:'25.000000',maximumMarkets:12,maximumOrderCost:'5.000000',quantity:1,latencyMs:3000,lifetimeMs:120000,maximumGapMs:120000,minimumSamples:4,minimumHistoryMs:120000,depthFractionBps:100,horizonSeconds:300},policies=[0,5,10,20].map(riskAversion=>({...base,riskAversion,id:'inventory-risk-'+riskAversion})),wallets=policies.map(createInventoryQuoteWalletV1),hasher=createHash('sha256'),stream=fs.createReadStream(file,{end:seal.bytes-1});stream.on('data',b=>hasher.update(b));let state=null,processed=0,firstAt=null;
for await(const line of readline.createInterface({input:stream,crlfDelay:Infinity})){const row=JSON.parse(line);if(!state)state=createBookPublicationState(row.payload.scope);state=applyBookPublication(state,row);if(Date.parse(row.at)<Date.parse(base.cutoff))continue;firstAt??=row.at;const event=row.kind==='book'?{kind:'book',at:row.at,book:row.payload.book,sequence:row.sequence,hash:row.hash}:{kind:'boundary',at:row.at,marketId:row.payload.marketId??null,sequence:row.sequence,hash:row.hash};for(let i=0;i<wallets.length;i++)advanceInventoryQuoteWalletV1(wallets[i],event,policies[i]);processed++;}
const st=fs.statSync(file);if(st.ino!==seal.ino||st.dev!==seal.dev||st.size<seal.bytes)throw Error('INVENTORY_REPLAY_SOURCE_CHANGED');const output={schemaVersion:1,createdAt:new Date().toISOString(),mode:'inventory_quote_seen_capture_development_replay_v1',source:{bytes:seal.bytes,sha256:hasher.digest('hex'),records:state.sequence,chainHash:state.hash,through:state.lastAt,fullSemanticReplay:true},firstAt,processed,elapsedMs:performance.now()-begun,cohorts:policies.map((policy,i)=>({policy,report:inventoryQuoteWalletReportV1(wallets[i],policy),fills:wallets[i].fills,redemptions:wallets[i].redemptions})),networkRequests:0,competitionOrders:0,profitabilityEstablished:false,limitations:['Previously seen development captures, not held-out or prospective evidence.','Strict later-book through fills are counterfactual; aggressor flow and queue priority are not proven.','Complementary redemption models documented normal netting; this is not contest execution.','Censored quote reservations and remaining inventory are not reset or counted as realized profit.']};fs.writeFileSync('data/inventory-quote-replay-20261007.json',JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify({processed,elapsedMs:output.elapsedMs,cohorts:output.cohorts.map(x=>({id:x.policy.id,...x.report}))}));
